candidates.raw:
size_t i;
adcs_vec3_t axis;
adcs_vec3_t h;
double norm;
double e;
double max_abs_speed;
size_t fastest_index;
adcs_status_t st;

if ((wheels == NULL) || (momentum == NULL) || (momentum_norm == NULL) ||
    (energy == NULL) || (fastest == NULL)) {
    return ADCS_E_NULL;
}

if (count != 4U) {
    *momentum = (adcs_vec3_t){0, 0, 0};
    *momentum_norm = 0.0;
    *energy = 0.0;
    *fastest = SIZE_MAX;
    return ADCS_E_RANGE;
}

h = (adcs_vec3_t){0, 0, 0};
e = 0.0;
max_abs_speed = -1.0;
fastest_index = SIZE_MAX;

for (i = 0U; i < count; i++) {
    if ((!isfinite(wheels[i].inertia_kg_m2)) || (wheels[i].inertia_kg_m2 <= 0.0) ||
        (!isfinite(wheels[i].speed_rad_s))) {
        *momentum = (adcs_vec3_t){0, 0, 0};
        *momentum_norm = 0.0;
        *energy = 0.0;
        *fastest = SIZE_MAX;
        return ADCS_E_RANGE;
    }
    st = adcs_vec3_normalize(&wheels[i].axis_body, ADCS_EPS_NORM, &axis);
    if (st != ADCS_OK) {
        *momentum = (adcs_vec3_t){0, 0, 0};
        *momentum_norm = 0.0;
        *energy = 0.0;
        *fastest = SIZE_MAX;
        return ADCS_E_RANGE;
    }
    {
        adcs_vec3_t term = adcs_vec3_scale(&axis, wheels[i].inertia_kg_m2 * wheels[i].speed_rad_s);
        h = adcs_vec3_add(&h, &term);
    }
    e += 0.5 * wheels[i].inertia_kg_m2 * wheels[i].speed_rad_s * wheels[i].speed_rad_s;
    if (fabs(wheels[i].speed_rad_s) > max_abs_speed) {
        max_abs_speed = fabs(wheels[i].speed_rad_s);
        fastest_index = i;
    }
}

*momentum = h;
norm = adcs_vec3_norm(&h);
*momentum_norm = norm;
*energy = e;
*fastest = fastest_index;
return ADCS_OK;

