double h_norm;
double e = 0.0;
double hx = 0.0, hy = 0.0, hz = 0.0;
double max_abs = 0.0;
size_t fastest_idx = SIZE_MAX;
adcs_status_t st;

if ((wheels == NULL) || (momentum == NULL) || (momentum_norm == NULL) ||
    (energy == NULL) || (fastest == NULL))
    return ADCS_E_NULL;

if (count != 4U) {
    *momentum = (adcs_vec3_t){0.0, 0.0, 0.0};
    *momentum_norm = 0.0;
    *energy = 0.0;
    *fastest = SIZE_MAX;
    return ADCS_E_RANGE;
}

/* validate every wheel: inertia finite & > 0, speed finite, axis normalizable */
for (i = 0; i < count; i++) {
    if ((!isfinite(wheels[i].inertia_kg_m2)) || (wheels[i].inertia_kg_m2 <= 0.0) ||
        (!isfinite(wheels[i].speed_rad_s)) ||
        (adcs_vec3_normalize(&wheels[i].axis_body, ADCS_EPS_NORM, &axis) != ADCS_OK)) {
        *momentum = (adcs_vec3_t){0.0, 0.0, 0.0};
        *momentum_norm = 0.0;
        *energy = 0.0;
        *fastest = SIZE_MAX;
        return ADCS_E_RANGE;
    }
}

/* linked body momentum via GNC primitive */
st = adcs_wheel_momentum(wheels, count, momentum);
if (st != ADCS_OK) {
    *momentum = (adcs_vec3_t){0.0, 0.0, 0.0};
    *momentum_norm = 0.0;
    *energy = 0.0;
    *fastest = SIZE_MAX;
    return ADCS_E_RANGE;
}
hx = momentum->x;
hy = momentum->y;
hz = momentum->z;
h_norm = sqrt(hx * hx + hy * hy + hz * hz);
*momentum_norm = h_norm;

/* rotational energy and fastest index */
for (i = 0; i < count; i++) {
    double abs_s;
    e += 0.5 * wheels[i].inertia_kg_m2 * wheels[i].speed_rad_s * wheels[i].speed_rad_s;
    abs_s = fabs(wheels[i].speed_rad_s);
    if (i == 0 || abs_s > max_abs) {
        max_abs = abs_s;
        fastest_idx = i;
    }
}
*energy = e;
*fastest = fastest_idx;

return ADCS_OK;

